import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['DIR','DL','RSPP-A','RSPP-AGG']
EA(K,'S01','Il datore di lavoro nelle società e nelle pubbliche amministrazioni',[SC("Chi è il datore di lavoro nella Srl?","Una Srl con 60 dipendenti ha un consiglio di amministrazione di tre membri. Uno di loro ha la delega gestoria su produzione e personale; gli altri due non hanno deleghe.",[
 ("Chi è il datore di lavoro ai fini della sicurezza?",[["Il consigliere con la delega gestoria su produzione e personale, perché ha i poteri decisionali e di spesa",True,"Corretto: il datore di lavoro è chi ha la responsabilità dell’organizzazione con poteri decisionali e di spesa."],["Il responsabile del personale",False,"Non ha i poteri dell’organo di vertice."],["Nessuno, la società è una persona giuridica",False,"La posizione di garanzia è di una persona fisica."]]),
 ("Gli altri due consiglieri non hanno alcun dovere?",[["Conservano doveri di controllo e di intervento sull’adeguatezza dell’assetto organizzativo",True,"Corretto: restano obblighi di vigilanza del consiglio."],["Nessun dovere",False,"Il consiglio mantiene doveri generali."],["Rispondono di ogni infortunio",False,"Non in modo automatico."]]),
 ("Il consigliere delegato può delegare a sua volta la valutazione dei rischi al direttore di stabilimento?",[["No: la valutazione dei rischi e la designazione dell’RSPP non sono delegabili",True,"Corretto: art. 17."],["Sì, con atto scritto",False,"Non per questi obblighi."],["Sì, se il direttore è ingegnere",False,"La qualifica non conta."]])],
 "Il datore di lavoro è chi ha i poteri decisionali e di spesa; il consiglio conserva doveri di controllo; valutazione dei rischi e nomina dell’RSPP restano indelegabili.","Una società con un consiglio di amministrazione. Individua il datore di lavoro.","Artt. 2, 17 e 18 D.lgs. 81/2008 · art. 2381 c.c.")])
EA(K,'S02','Il dirigente: definizione, poteri e limiti',[LB("Laboratorio · Il dirigente di fatto","Analizzi la posizione del capo reparto stampaggio di un’impresa metalmeccanica.",[
  ["Inquadramento","impiegato di settimo livello, non dirigente secondo il contratto"],["Compiti","organizza turni e attribuzione delle macchine, approva acquisti fino a 5.000 €, decide le priorità di manutenzione del reparto"],["Collaboratori","3 capiturno e 25 operai"],["Evento","un operaio si ferisce su una pressa con il riparo rimosso da settimane"]],[
  ("Il capo reparto è dirigente ai fini della sicurezza? Motiva.",6,"Sì: la qualifica prevenzionistica dipende dai poteri effettivamente esercitati. Organizza il lavoro, dispone di risorse e decide sulla manutenzione: attua le direttive del datore di lavoro organizzando l’attività e vigilando su di essa, come previsto dall’art. 2, lett. d).",["Ho applicato il principio di effettività","Ho collegato i poteri alla definizione","Ho ignorato l’inquadramento contrattuale"]),
  ("Quali obblighi aveva rispetto alla pressa?",6,"Gli obblighi dell’art. 18 nell’ambito delle sue attribuzioni: richiedere l’osservanza delle norme, garantire attrezzature conformi e la loro manutenzione, prendere misure appropriate, vigilare che i preposti facciano rispettare le regole. Con un riparo rimosso da settimane doveva intervenire e fermare la macchina.",["Ho citato l’art. 18","Ho collegato manutenzione e conformità","Ho indicato il dovere di intervenire"]),
  ("Chi altro potrebbe essere chiamato a rispondere?",6,"Il capoturno come preposto, se ha tollerato la prassi; il datore di lavoro, per gli aspetti organizzativi e per la vigilanza; l’impresa ai sensi dell’art. 25-septies del D.lgs. 231/2001 se il reato ha procurato un interesse o vantaggio, ad esempio risparmio di tempo, e manca un modello efficace.",["Ho considerato il preposto","Ho considerato il datore di lavoro","Ho considerato l’ente"])],
 "Nel laboratorio analizzi la posizione di un capo reparto dopo un infortunio. Stabilisci se è dirigente ai fini della sicurezza, quali obblighi aveva e chi altro potrebbe rispondere, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 2, 18, 19 e 299 D.lgs. 81/2008")])
EA(K,'S03','La delega di funzioni',[LB("Laboratorio · Scrivere una delega di funzioni","Il datore di lavoro di un’impresa con tre stabilimenti vuole delegare al direttore tecnico la gestione della sicurezza delle macchine e degli impianti.",[
  ["Delegato","direttore tecnico, ingegnere, 15 anni di esperienza"],["Budget proposto","nessun budget dedicato: ogni spesa va approvata dal datore di lavoro"],["Forma prevista","comunicazione via e-mail"]],[
  ("Elenca i requisiti di validità della delega e indica quali mancano.",7,"Atto scritto con data certa; professionalità ed esperienza del delegato; poteri di organizzazione, gestione e controllo; autonomia di spesa necessaria; accettazione scritta; adeguata e tempestiva pubblicità. Mancano la forma scritta con data certa e l’autonomia di spesa; vanno previste anche accettazione e pubblicità.",["Ho elencato i requisiti dell’art. 16","Ho rilevato la mancanza dell’autonomia di spesa","Ho rilevato la forma inadeguata"],None,150),
  ("Quali obblighi non può comprendere la delega?",5,"La valutazione di tutti i rischi con l’elaborazione del DVR e la designazione dell’RSPP, indelegabili ai sensi dell’art. 17.",["Ho indicato il DVR","Ho indicato la designazione dell’RSPP"]),
  ("Come esercita il datore di lavoro la vigilanza sul delegato?",6,"Con verifiche sull’organizzazione e sui risultati, non su ogni singola lavorazione: report periodici, audit, indicatori, riesame. La vigilanza si presume assolta se è adottato ed efficacemente attuato il modello di verifica e controllo dell’art. 30, comma 4.",["Ho descritto strumenti di vigilanza","Ho citato il modello dell’art. 30","Ho distinto vigilanza e controllo puntuale"])],
 "Nel laboratorio verifichi una delega di funzioni che il datore di lavoro vorrebbe conferire al direttore tecnico. Individua i requisiti mancanti, gli obblighi esclusi e come esercitare la vigilanza, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 16, 17 e 30 D.lgs. 81/2008")])
EA(K,'S04','La responsabilità dell’ente: art. 25-septies D.lgs. 231/2001',[ES("Esempio guidato · La sanzione all’ente per un infortunio mortale","Il sistema per quote applicato all’art. 25-septies.",[
 ["Il reato","Omicidio colposo commesso con violazione dell’art. 55, comma 2, in un’azienda a rischio particolare.","Art. 25-septies, c. 1"],
 ["Le quote","La sanzione è pari a 1.000 quote.","1.000 quote"],
 ["Il valore della quota","Il giudice lo fissa tra 258 e 1.549 € secondo le condizioni economiche dell’ente: ad esempio 500 €.","500 € per quota"],
 ["La sanzione pecuniaria","1.000 × 500 = 500.000 €.","500.000 €"],
 ["Le interdittive","Si aggiungono sanzioni interdittive per una durata non inferiore a tre mesi e non superiore a un anno.","Da 3 mesi a 1 anno"]],
 "Vediamo la sanzione all’ente nel caso più grave. Per l’omicidio colposo commesso con violazione dell’articolo cinquantacinque, comma due, la sanzione è di mille quote. Se il giudice fissa la quota a cinquecento euro, la sanzione è di cinquecentomila euro, a cui si aggiungono sanzioni interdittive da tre mesi a un anno. Un modello organizzativo efficace è la principale difesa.","D.lgs. 231/2001, artt. 10, 11 e 25-septies")])
EA(K,'S05','Misurare le prestazioni: indicatori reattivi e proattivi',[ES("Esempio guidato · Indice di frequenza e di gravità","Gli indicatori della UNI 7249 per un’impresa con 180 dipendenti.",[
 ["I dati","4 infortuni con assenza, 110 giornate perse, 320.000 ore lavorate nell’anno.","4 · 110 · 320.000"],
 ["Indice di frequenza","IF = infortuni × 1.000.000 / ore lavorate = 4 × 1.000.000 / 320.000.","IF = 12,5"],
 ["Indice di gravità","IG = giornate perse × 1.000 / ore lavorate = 110 × 1.000 / 320.000.","IG ≈ 0,34"],
 ["Il confronto","Si confrontano con gli anni precedenti e con il settore, a parità di metodo.","Trend e benchmark"],
 ["Gli indicatori proattivi","Si affiancano quasi incidenti segnalati, sopralluoghi svolti, azioni chiuse nei tempi.","Prevenire, non solo contare"]],
 "Calcoliamo gli indici infortunistici. Con quattro infortuni e trecentoventimila ore lavorate, l’indice di frequenza vale dodici e mezzo. Con centodieci giornate perse, l’indice di gravità vale circa zero virgola trentaquattro. Questi indicatori reattivi vanno confrontati nel tempo e affiancati da indicatori proattivi, come le segnalazioni di quasi incidenti e le azioni chiuse nei tempi.","UNI 7249:2007")])
EA(K,'S06','L’ispezione: poteri degli organi di vigilanza e sospensione dell’attività',[SC("L’ispettore in reparto","Un ispettore dell’ASL si presenta senza preavviso e chiede di visitare il reparto saldatura e di vedere il DVR e i registri della formazione.",[
 ("Come ti comporti?",[["Collabori: lo accompagni, metti a disposizione i documenti e annoti ciò che viene esaminato",True,"Corretto: gli ispettori hanno poteri di accesso e di esame dei documenti."],["Gli chiedi di tornare con un appuntamento",False,"L’accesso non richiede preavviso."],["Neghi l’accesso finché non arriva il datore di lavoro",False,"Ostacolare l’ispezione è un illecito."]]),
 ("L’ispettore chiede di sentire due lavoratori senza la presenza dei responsabili. È ammesso?",[["Sì, può assumere informazioni dai lavoratori",True,"Corretto."],["No, serve sempre un dirigente presente",False,"Non è un requisito."],["Solo con un avvocato",False,"Non è necessario."]]),
 ("Al termine riceve un verbale con prescrizioni. Che cosa fai?",[["Organizzi l’adempimento nei termini, con responsabili e prove, e chiedi per tempo una proroga motivata se necessario",True,"Corretto: la regolarizzazione consente di estinguere le contravvenzioni."],["Lo archivi",False,"I termini decorrono."],["Contesti tutto senza adempiere",False,"Si può contestare, ma i termini vanno gestiti."]])],
 "Collaborare all’ispezione, consentire l’accesso a luoghi, documenti e lavoratori, gestire le prescrizioni nei termini: così l’impresa tutela sé stessa e i lavoratori.","Un’ispezione senza preavviso. Gestisci la visita e le conseguenze.","Art. 13 D.lgs. 81/2008 · D.lgs. 758/1994")])
EA(K,'S07','La prescrizione e l’estinzione delle contravvenzioni',[ES("Esempio guidato · Estinguere una contravvenzione","La procedura del D.lgs. 758/1994.",[
 ["La violazione","L’ispettore accerta che alcuni lavoratori non hanno ricevuto la formazione specifica.","Contravvenzione"],
 ["La prescrizione","Termine di 60 giorni per completare la formazione, prorogabile una sola volta su richiesta motivata.","Adempiere nel termine"],
 ["La verifica","Entro 60 giorni dalla scadenza l’organo di vigilanza verifica l’adempimento.","Verifica"],
 ["Il pagamento","Il contravventore è ammesso a pagare un quarto del massimo dell’ammenda entro 30 giorni: con un massimo indicativo di 7.000 €, 1.750 €.","¼ del massimo"],
 ["L’estinzione","Con adempimento e pagamento la contravvenzione si estingue.","Estinzione"]],
 "Seguiamo la procedura di estinzione. L’ispettore accerta che alcuni lavoratori non hanno la formazione specifica e prescrive di completarla entro sessanta giorni. Verificato l’adempimento, il contravventore paga un quarto del massimo dell’ammenda entro trenta giorni: con un massimo indicativo di settemila euro, sono millesettecentocinquanta euro. Così la contravvenzione si estingue.","D.lgs. 758/1994, artt. 20-24 · art. 301 D.lgs. 81/2008")])
# ── organizzazione ──
EA(K,'S08','La riunione periodica: contenuti e verbale',[LB("Laboratorio · Preparare la riunione periodica","Prepari la riunione periodica annuale di un’impresa con 70 lavoratori.",[
  ["Dati dell’anno","3 infortuni, di cui uno con 40 giorni di assenza; 12 quasi incidenti segnalati; 2 giudizi di idoneità con limitazioni"],["Novità","nuova linea di verniciatura installata a settembre"],["Formazione","8 lavoratori con aggiornamento scaduto"]],[
  ("Scrivi l’ordine del giorno.",6,"Esame del DVR e del suo aggiornamento per la nuova linea; andamento di infortuni, quasi incidenti e sorveglianza sanitaria; criteri di scelta ed efficacia dei DPI, in particolare per la verniciatura; programmi di informazione e formazione e recupero degli aggiornamenti scaduti; eventuali obiettivi di miglioramento e codici di comportamento.",["Ho incluso DVR e nuova linea","Ho incluso infortuni e sorveglianza","Ho incluso DPI e formazione"]),
  ("Chi convochi e quali dati chiedi a ciascuno?",5,"Datore di lavoro o suo rappresentante, RSPP, medico competente, RLS. All’RSPP l’analisi degli infortuni e lo stato del DVR; al medico competente la relazione anonima e collettiva sulla sorveglianza; all’RLS le segnalazioni dei lavoratori.",["Ho indicato i quattro partecipanti","Ho chiesto dati a ciascuno"]),
  ("Che cosa deve contenere il verbale?",6,"Data e partecipanti, argomenti trattati, esiti e decisioni, azioni con responsabili e scadenze, osservazioni dell’RLS; il verbale è a disposizione dei partecipanti per la consultazione.",["Ho previsto decisioni e responsabili","Ho previsto le osservazioni dell’RLS","Ho previsto la disponibilità del verbale"])],
 "Nel laboratorio prepari la riunione periodica annuale di un’impresa con settanta lavoratori. Scrivi l’ordine del giorno, individua partecipanti e dati da raccogliere e definisci i contenuti del verbale, poi confronta ogni risposta con la soluzione di riferimento.","Art. 35 D.lgs. 81/2008")])
EA(K,'S09','Esempio applicativo: il DUVRI per un appalto di manutenzione',[LB("Laboratorio · Il DUVRI per le pulizie","Affidi le pulizie notturne e il lavaggio dei pavimenti del reparto produttivo a un’impresa esterna.",[
  ["Orario","dalle 22 alle 2, con il terzo turno di produzione attivo in parte del reparto"],["Attività dell’appaltatore","lavasciuga, prodotti detergenti, scale portatili per le vetrate"],["Rischi del committente","carrelli elevatori in movimento, prodotti chimici di processo, rumore"]],[
  ("Individua le interferenze.",6,"Passaggio dei carrelli nelle aree in lavaggio e pavimenti bagnati con rischio di scivolamento; uso di detergenti vicino a prodotti chimici di processo, con possibili incompatibilità; lavori in quota sulle scale in aree con transito; rumore e comunicazione difficile; gestione delle emergenze notturne.",["Ho individuato carrelli e pavimenti bagnati","Ho considerato le incompatibilità chimiche","Ho considerato emergenze e comunicazione"]),
  ("Proponi le misure di coordinamento.",7,"Separazione temporale o spaziale: lavaggio solo nelle aree senza produzione, delimitate e segnalate; percorsi dei carrelli definiti; schede di sicurezza scambiate e divieto di miscelare prodotti; scale solo in aree interdette al transito; referente del committente reperibile; informazione sulle procedure di emergenza e sui punti di raccolta.",["Ho previsto separazione e segnaletica","Ho previsto lo scambio delle SDS","Ho previsto referente ed emergenze"],None,120),
  ("Che cosa resta da definire nel contratto?",5,"Costi della sicurezza da interferenze non soggetti a ribasso, allegato DUVRI, verifica dell’idoneità tecnico-professionale, nominativo del referente dell’appaltatore e, per gli appalti, il personale munito di tessera di riconoscimento.",["Ho indicato i costi della sicurezza","Ho indicato l’idoneità tecnico-professionale","Ho indicato la tessera di riconoscimento"])],
 "Nel laboratorio prepari il DUVRI per un appalto di pulizie notturne in un reparto in parte attivo. Individua le interferenze, proponi le misure di coordinamento e completa gli elementi contrattuali, poi confronta ogni risposta con la soluzione di riferimento.","Art. 26 D.lgs. 81/2008")])
EA(K,'S10','La patente a crediti: funzionamento e decurtazioni',[SC("Il subappaltatore senza crediti","Un’impresa edile appaltatrice vuole affidare in subappalto le opere di carpenteria a una piccola impresa. Dalla verifica risulta una patente con 12 crediti.",[
 ("Il subappaltatore può operare in cantiere?",[["No: con meno di 15 crediti non può operare nei cantieri temporanei o mobili",True,"Corretto."],["Sì, se firma un impegno",False,"Il limite è di legge."],["Sì, per lavori sotto i 100.000 €",False,"Non esiste questa soglia."]]),
 ("Chi deve verificare la patente?",[["Il committente o il responsabile dei lavori, e l’appaltatore nella scelta del subappaltatore",True,"Corretto: la verifica fa parte dell’idoneità tecnico-professionale."],["Nessuno, la verifica è dell’INL",False,"La verifica è un obbligo dei soggetti della filiera."],["Solo il coordinatore per l’esecuzione",False,"Non solo."]]),
 ("Che cosa rischia chi fa operare un’impresa senza i crediti necessari?",[["Sanzioni rilevanti, con un minimo che dopo il D.L. 159/2025 è di 12.000 €, e l’esclusione dai lavori",True,"Corretto."],["Nulla",False,"Le sanzioni sono significative."],["Solo un richiamo",False,"Sono sanzioni pecuniarie."]])],
 "La patente a crediti si verifica prima di ogni affidamento: sotto i quindici crediti l’impresa non entra in cantiere.","Un subappaltatore con pochi crediti. Decidi se può lavorare.","Art. 27 D.lgs. 81/2008 · D.L. 159/2025")])
EA(K,'S11','D.P.R. 177/2011: requisiti di qualificazione delle imprese',[SC("La vasca da pulire","Un’impresa alimentare deve far pulire l’interno di una vasca interrata di raccolta delle acque di processo, con accesso da un passo d’uomo.",[
 ("Che cosa è la vasca ai fini della sicurezza?",[["Un ambiente sospetto di inquinamento o confinato, soggetto al D.P.R. 177/2011",True,"Corretto: accesso limitato, possibile mancanza di ossigeno o presenza di gas."],["Un normale luogo di lavoro",False,"Ha rischi specifici gravi."],["Un luogo dove non si applica nessuna regola",False,"Le regole sono stringenti."]]),
 ("Quali requisiti deve avere l’impresa appaltatrice?",[["Almeno il 30% della forza lavoro con esperienza triennale, compreso il preposto, formazione e addestramento specifici e DPI e attrezzature idonei",True,"Corretto."],["Solo l’iscrizione alla Camera di commercio",False,"Non basta."],["Basta il preposto esperto",False,"Servono i requisiti per tutta la squadra."]]),
 ("Che cosa deve fare il committente prima dei lavori?",[["Individuare un proprio rappresentante, informare sui rischi e definire una procedura di lavoro con misurazioni dell’atmosfera e soccorso",True,"Corretto: il soccorso deve essere organizzato prima dell’ingresso."],["Fornire solo le chiavi del passo d’uomo",False,"È insufficiente."],["Chiamare il 112 se succede qualcosa",False,"Il soccorso va pianificato."]])],
 "Ambienti confinati: imprese qualificate, procedura scritta, misure dell’atmosfera, rappresentante del committente e soccorso organizzato prima di entrare.","Una vasca interrata da pulire. Verifica requisiti e procedure.","D.P.R. 177/2011 · artt. 66 e 121 D.lgs. 81/2008")])
EA(K,'S12','Gli addetti antincendio: il D.M. 2 settembre 2021',[ES("Esempio guidato · Quale corso per gli addetti antincendio?","Dal livello di rischio alla formazione.",[
 ["L’attività","Un magazzino con materiali combustibili, classificato a rischio medio nella valutazione del rischio di incendio.","Livello 2"],
 ["Il corso","Per il livello 2 il corso è di 8 ore, con parte pratica.","8 ore"],
 ["L’aggiornamento","Ogni cinque anni, 5 ore.","5 ore / 5 anni"],
 ["Il numero","Gli addetti devono essere presenti in ogni turno, in numero adeguato a dimensioni e organizzazione.","Copertura di tutti i turni"],
 ["Il confronto","Rischio basso: 4 ore e aggiornamento di 2; rischio elevato: 16 ore e aggiornamento di 8.","4 · 8 · 16 ore"]],
 "Scegliamo il corso per gli addetti antincendio. Il magazzino è a rischio medio: serve il livello due, con un corso di otto ore e un aggiornamento di cinque ore ogni cinque anni. Gli addetti devono coprire tutti i turni. Per confronto, il livello uno richiede quattro ore e il livello tre sedici.","D.M. 2 settembre 2021")])
EA(K,'S13','Il costo della non sicurezza e gli incentivi',[LB("Laboratorio · Il costo di un infortunio","Stimi il costo di un infortunio per presentarlo alla direzione.",[
  ["Evento","schiacciamento di una mano su una pressa; 60 giorni di assenza"],["Retribuzione","costo aziendale del lavoratore 180 € al giorno"],["Effetti","fermo della pressa 3 giorni; 40 ore di straordinario dei colleghi a 30 €/h; 20 ore di tempo di dirigenti e RSPP a 50 €/h; consegna in ritardo con penale di 4.000 €"],["Prescrizione dell’ASL","adeguamento della pressa: 6.000 €"]],[
  ("Separa i costi diretti da quelli indiretti.",6,"Diretti: retribuzione a carico dell’impresa nei primi giorni e integrazioni previste, adeguamento prescritto, eventuali sanzioni e spese legali. Indiretti: fermo della macchina, straordinari, tempo di gestione, penale, danno di immagine e clima aziendale.",["Ho distinto le due categorie","Ho inserito la penale tra gli indiretti","Ho considerato i costi non monetari"]),
  ("Stima gli importi principali.",7,"Straordinari: 40 × 30 = 1.200 €. Tempo di gestione: 20 × 50 = 1.000 €. Penale: 4.000 €. Adeguamento: 6.000 €. Già così si superano 12.000 €, senza contare fermo produttivo, integrazioni retributive, eventuale contenzioso e danno differenziale.",["Ho calcolato straordinari e tempo","Ho sommato oltre 12.000 €","Ho indicato i costi non stimati"]),
  ("Come presenti il dato alla direzione?",5,"Confrontandolo con il costo della prevenzione: il riparo interbloccato e la manutenzione sarebbero costati molto meno; proporre un piano di verifica delle presse e gli incentivi INAIL disponibili.",["Ho confrontato con il costo della prevenzione","Ho proposto un piano","Ho citato gli incentivi"])],
 "Nel laboratorio stimi il costo di un infortunio su una pressa. Distingui costi diretti e indiretti, calcola gli importi principali e prepara il messaggio per la direzione, poi confronta ogni risposta con la soluzione di riferimento.","INAIL · art. 2087 c.c.")])
EA(K,'S14','Gli incentivi INAIL per la prevenzione',[ES("Esempio guidato · La riduzione del tasso per prevenzione","Quanto vale la domanda all’INAIL.",[
 ["L’impresa","40 lavoratori; premio INAIL annuo di 60.000 €.","11-50 lavoratori"],
 ["Gli interventi","Interventi migliorativi oltre gli obblighi di legge realizzati nell’anno precedente, con punteggio almeno pari a 100.","Punteggio ≥ 100"],
 ["La domanda","Con il modulo dedicato entro il 28 febbraio.","Entro il 28 febbraio"],
 ["La riduzione","Per le imprese da 11 a 50 lavoratori la riduzione è del 18%.","60.000 × 18% = 10.800 €"],
 ["Il confronto","Fino a 10 lavoratori 28%; da 51 a 200 10%; oltre 200 5%.","28 · 18 · 10 · 5%"]],
 "Vediamo quanto vale la riduzione del tasso per prevenzione. Un’impresa con quaranta lavoratori e un premio di sessantamila euro ha realizzato interventi migliorativi con almeno cento punti. Presentando la domanda entro il ventotto febbraio ottiene una riduzione del diciotto per cento, cioè diecimilaottocento euro.","Modalità di applicazione delle tariffe INAIL, art. 23 · modulo OT23")])
